// LinkedIn — Shortest Word Distance II (LeetCode 244): many queries on one list; then III (245): w1 may equal w2.
public sealed class WordDistance {
    readonly Dictionary<string, List<int>> _pos = new();

    public WordDistance(string[] words) {
        for (int i = 0; i < words.Length; i++) {
            if (!_pos.TryGetValue(words[i], out var l)) _pos[words[i]] = l = new List<int>();
            l.Add(i);                                                // indices come out sorted
        }
    }

    // Two sorted index lists, merged with two pointers: O(a + b) per query.
    public int Shortest(string w1, string w2) {
        if (!_pos.TryGetValue(w1, out var a) || !_pos.TryGetValue(w2, out var b)) throw new KeyNotFoundException();
        if (w1 == w2) {                                              // III: nearest two occurrences of the same word
            if (a.Count < 2) throw new ArgumentException("the word occurs only once");
            int m = int.MaxValue;
            for (int k = 1; k < a.Count; k++) m = Math.Min(m, a[k] - a[k - 1]);
            return m;
        }
        int i = 0, j = 0, best = int.MaxValue;
        while (i < a.Count && j < b.Count) {
            best = Math.Min(best, Math.Abs(a[i] - b[j]));
            if (a[i] < b[j]) i++; else j++;
        }
        return best;
    }
}
